//go:build linux

package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"strings"
	"time"

	"github.com/aonsyed/cyberpanel/platform/internal/apiserver"
	"github.com/aonsyed/cyberpanel/platform/internal/apps"
)

type securityEdge struct{store apps.SQLRepository;client *apps.LinuxApplicationClient;recovery *apps.LinuxApplicationRecoveryProvider;scanner apps.ScanCoordinator;remediator apps.RemediationCoordinator;now func()time.Time}

func newSecurityEdge(store apps.SQLRepository,client *apps.LinuxApplicationClient,recovery *apps.LinuxApplicationRecoveryProvider,now func()time.Time)(*securityEdge,error){if store.DB==nil||client==nil||recovery==nil{return nil,apps.ErrInvalid};if now==nil{now=time.Now};scanner:=apps.ScanCoordinator{Store:store,Snapshots:client,Providers:map[string]apps.ScannerProvider{client.ID():client},Now:now};return &securityEdge{store:store,client:client,recovery:recovery,scanner:scanner,remediator:apps.RemediationCoordinator{Store:store,Snapshots:client,Recovery:recovery,Executor:client,Scanner:scanner,Now:now},now:now},nil}

func(edge *securityEdge)ListFindings(ctx context.Context,call apiserver.EdgeCall,page apiserver.EdgePagePayload)(apiserver.EdgePage[apiserver.SecurityFindingProjection],error){if call.TenantID==""{return apiserver.EdgePage[apiserver.SecurityFindingProjection]{},apps.ErrPolicyDenied};items,next,err:=edge.store.ListScopedFindings(ctx,apps.TenantID(call.TenantID),"","",page.Limit,page.Cursor);if err!=nil{return apiserver.EdgePage[apiserver.SecurityFindingProjection]{},err};result:=make([]apiserver.SecurityFindingProjection,0,len(items));for _,item:=range items{item,err=edge.expireSuppression(ctx,item);if err!=nil{return apiserver.EdgePage[apiserver.SecurityFindingProjection]{},err};result=append(result,securityFindingProjection(item))};return apiserver.EdgePage[apiserver.SecurityFindingProjection]{Items:result,NextCursor:next},nil}

func(edge *securityEdge)GetFinding(ctx context.Context,call apiserver.EdgeCall)(apiserver.SecurityFindingProjection,error){finding,err:=edge.load(ctx,call);if err!=nil{return apiserver.SecurityFindingProjection{},err};finding,err=edge.expireSuppression(ctx,finding);if err!=nil{return apiserver.SecurityFindingProjection{},err};return securityFindingProjection(finding),nil}

func(edge *securityEdge)StartScan(ctx context.Context,call apiserver.EdgeCall,payload apiserver.SecurityScanPayload)(apiserver.EdgeMutation[apiserver.SecurityFindingProjection],error){installations,err:=edge.scanTargets(ctx,call,payload.Scope);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};var selected *apps.Finding;var files,found uint64;for _,installation:=range installations{scope,scopeErr:=edge.client.ResolveExecutionScope(ctx,installation);if scopeErr!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},scopeErr};run:=edge.scanRun(call,installation,payload.Depth,nil);scanContext,cancel:=context.WithTimeout(ctx,run.Budget.MaximumDuration);result,runErr:=edge.scanner.Run(scanContext,run,scope,nil);cancel();if runErr!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},runErr};files+=result.FilesScanned;found+=uint64(len(result.Findings));if err=edge.supersedeAbsent(ctx,installation.ID,run.ID,result.Findings);err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};for _,reported:=range result.Findings{persisted,loadErr:=edge.store.LoadFinding(ctx,reported.ID);if loadErr!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},loadErr};if selected==nil||securitySeverityRank(persisted.Severity)>securitySeverityRank(selected.Severity){value:=persisted;selected=&value}}};operationID:="security-scan-"+securityEdgeDigest(call.CommandID)[:40];state:="completed";projection:=apiserver.SecurityFindingProjection{ID:operationID,Kind:"application-scan",Severity:"informational",ResourceKind:"tenant",ResourceID:call.TenantID,Summary:"Security scan completed: "+securityUint(found)+" findings across "+securityUint(files)+" files",State:state,EvidenceDigest:securityEdgeDigest(operationID,securityUint(files),securityUint(found)),Generation:1,UpdatedAt:edge.now().UTC()};if selected!=nil{projection=securityFindingProjection(*selected)};return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{OperationID:operationID,State:state,Generation:projection.Generation,Resource:projection},nil}

func(edge *securityEdge)ApplyRemediation(ctx context.Context,call apiserver.EdgeCall,payload apiserver.SecurityRemediationPayload)(apiserver.EdgeMutation[apiserver.SecurityFindingProjection],error){if payload.Strategy!="quarantine"{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},apps.ErrUnsupported};finding,err:=edge.load(ctx,call);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};if finding.State!=apps.FindingOpen||call.ExpectedGeneration!=finding.Generation||securityNormalizeDigest(payload.EvidenceDigest)!=finding.EvidenceDigest{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},apps.ErrConflict};installation,err:=edge.store.LoadInstallation(ctx,finding.InstallationID);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};scope,err:=edge.client.ResolveExecutionScope(ctx,installation);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};recoveryPoint,_,err:=edge.recovery.CreateRecoveryPoint(ctx,apps.RecoveryRequest{TenantID:finding.TenantID,SiteID:finding.SiteID,InstallationID:finding.InstallationID,Purpose:"security_remediation",Consistency:"application_consistent",Required:true});if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};now:=edge.now().UTC();approval:=securityEdgeDigest(call.CommandID,call.PrincipalID,finding.EvidenceDigest,payload.Strategy);plan:=apps.RemediationPlan{ID:apps.RemediationPlanID("remediation-"+securityEdgeDigest(call.CommandID,string(finding.ID))[:48]),CommandID:apps.CommandID(call.CommandID),TenantID:finding.TenantID,SiteID:finding.SiteID,InstallationID:finding.InstallationID,FindingIDs:[]apps.FindingID{finding.ID},Action:apps.RemediationQuarantine,Paths:[]apps.RelativePath{finding.Path},ExpectedDigests:map[string]string{finding.Path.String():finding.ContentDigest},RecoveryPointID:recoveryPoint,ApprovedBy:call.PrincipalID,ApprovalDigest:approval,State:apps.RemediationApproved,CreatedAt:now,UpdatedAt:now,Generation:1};if err=edge.store.CreateRemediation(ctx,plan);err!=nil{prior,loadErr:=edge.store.LoadRemediation(ctx,plan.ID);if loadErr!=nil||prior.CommandID!=plan.CommandID||prior.ApprovalDigest!=plan.ApprovalDigest{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};plan=prior};verification:=edge.scanRun(apiserver.EdgeCall{CommandID:"verify-"+securityEdgeDigest(call.CommandID,string(finding.ID))[:48]},installation,"deep",[]apps.RelativePath{finding.Path});committed,err:=edge.remediator.Apply(ctx,plan,scope,verification,nil);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};finding.State=apps.FindingRemediated;finding.SuppressedBy="";finding.SuppressionReason="";finding.SuppressedUntil=time.Time{};finding.Generation++;finding.LastSeenAt=edge.now().UTC();if err=edge.store.UpdateFinding(ctx,finding,finding.Generation-1);err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};projection:=securityFindingProjection(finding);return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{OperationID:string(committed.ID),State:string(committed.State),Generation:finding.Generation,Resource:projection},nil}

func(edge *securityEdge)SuppressFinding(ctx context.Context,call apiserver.EdgeCall,payload apiserver.SecuritySuppressPayload)(apiserver.EdgeMutation[apiserver.SecurityFindingProjection],error){finding,err:=edge.load(ctx,call);if err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};if finding.State!=apps.FindingOpen||call.ExpectedGeneration!=finding.Generation||securityNormalizeDigest(payload.EvidenceDigest)!=finding.EvidenceDigest{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},apps.ErrConflict};finding.State=apps.FindingAccepted;finding.SuppressedBy=call.PrincipalID;finding.SuppressionReason=strings.TrimSpace(payload.Reason);finding.SuppressedUntil=payload.ExpiresAt.UTC();finding.Generation++;finding.LastSeenAt=edge.now().UTC();if err=edge.store.UpdateFinding(ctx,finding,finding.Generation-1);err!=nil{return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{},err};projection:=securityFindingProjection(finding);return apiserver.EdgeMutation[apiserver.SecurityFindingProjection]{OperationID:call.CommandID,State:string(finding.State),Generation:finding.Generation,Resource:projection},nil}

func(edge *securityEdge)load(ctx context.Context,call apiserver.EdgeCall)(apps.Finding,error){if call.TenantID==""{return apps.Finding{},apps.ErrPolicyDenied};finding,err:=edge.store.LoadFinding(ctx,apps.FindingID(call.ResourceID));if err!=nil{return apps.Finding{},err};if string(finding.TenantID)!=call.TenantID{return apps.Finding{},apps.ErrNotFound};return finding,nil}

func(edge *securityEdge)expireSuppression(ctx context.Context,finding apps.Finding)(apps.Finding,error){if finding.State!=apps.FindingAccepted||finding.SuppressedUntil.IsZero()||finding.SuppressedUntil.After(edge.now().UTC()){return finding,nil};expected:=finding.Generation;finding.State=apps.FindingOpen;finding.SuppressedBy="";finding.SuppressionReason="";finding.SuppressedUntil=time.Time{};finding.Generation++;finding.LastSeenAt=edge.now().UTC();if err:=edge.store.UpdateFinding(ctx,finding,expected);err!=nil{return apps.Finding{},err};return finding,nil}

func(edge *securityEdge)scanTargets(ctx context.Context,call apiserver.EdgeCall,scope string)([]apps.ApplicationInstallation,error){if call.TenantID==""{return nil,apps.ErrPolicyDenied};if scope!=""{installation,err:=edge.store.LoadInstallation(ctx,apps.InstallationID(scope));if err!=nil{return nil,err};if string(installation.TenantID)!=call.TenantID{return nil,apps.ErrNotFound};return []apps.ApplicationInstallation{installation},nil};items:=[]apps.ApplicationInstallation{};cursor:="";for{page,next,err:=edge.store.ListInstallations(ctx,apps.TenantID(call.TenantID),"",500,cursor);if err!=nil{return nil,err};for _,item:=range page{switch item.State{case apps.InstallationActive,apps.InstallationMaintenance,apps.InstallationDegraded,apps.InstallationQuarantined:items=append(items,item)}};if next==""{break};cursor=next};if len(items)==0{return nil,apps.ErrNotFound};return items,nil}

func(edge *securityEdge)scanRun(call apiserver.EdgeCall,installation apps.ApplicationInstallation,depth string,paths []apps.RelativePath)apps.ScanRun{mode:=apps.ScanFull;duration:=time.Hour;files:=uint64(1000000);bytes:=uint64(256<<30);if depth=="quick"{mode=apps.ScanQuick;duration=15*time.Minute;files=200000;bytes=64<<30}else if len(paths)>0{mode=apps.ScanCustom}else if depth=="deep"{duration=4*time.Hour;files=5000000;bytes=1<<40};now:=edge.now().UTC();identity:=securityEdgeDigest(call.CommandID,string(installation.ID));return apps.ScanRun{ID:apps.ScanRunID("scan-"+identity[:48]),CommandID:apps.CommandID("scan-command-"+identity[:48]),TenantID:installation.TenantID,SiteID:installation.SiteID,InstallationID:installation.ID,Mode:mode,ProviderID:edge.client.ID(),ProviderKind:edge.client.Kind(),RulesVersion:"cyberpanel-local-2026.08.1",EngineVersion:"archive-stream-v1",CustomPaths:paths,Budget:apps.ScanBudget{MaximumDuration:duration,MaximumFiles:files,MaximumBytes:bytes,MaximumExpandedBytes:bytes*2,MaximumArchiveDepth:8,MaximumMemoryBytes:256<<20,MaximumCPUPercent:50,MaximumIOBytesPerSecond:128<<20},State:apps.ScanAdmitted,CreatedAt:now,UpdatedAt:now}}

func(edge *securityEdge)supersedeAbsent(ctx context.Context,installation apps.InstallationID,run apps.ScanRunID,current []apps.Finding)error{seen:=map[apps.FindingID]bool{};for _,item:=range current{seen[item.ID]=true};cursor:="";for{items,next,err:=edge.store.ListScopedFindings(ctx,"",installation,"",500,cursor);if err!=nil{return err};for _,item:=range items{if seen[item.ID]||item.ScanRunID==run||item.State!=apps.FindingOpen&&item.State!=apps.FindingAccepted{continue};expected:=item.Generation;item.State=apps.FindingSuperseded;item.SuppressedBy="";item.SuppressionReason="";item.SuppressedUntil=time.Time{};item.Generation++;item.LastSeenAt=edge.now().UTC();if err=edge.store.UpdateFinding(ctx,item,expected);err!=nil{return err}};if next==""{return nil};cursor=next}}

func securityFindingProjection(finding apps.Finding)apiserver.SecurityFindingProjection{return apiserver.SecurityFindingProjection{ID:string(finding.ID),Kind:finding.SignatureID,Severity:string(finding.Severity),ResourceKind:"application",ResourceID:string(finding.InstallationID),Summary:finding.Reason,State:string(finding.State),EvidenceDigest:finding.EvidenceDigest,Generation:finding.Generation,UpdatedAt:finding.LastSeenAt}}
func securitySeverityRank(value apps.FindingSeverity)int{switch value{case apps.SeverityCritical:return 5;case apps.SeverityHigh:return 4;case apps.SeverityMedium:return 3;case apps.SeverityLow:return 2;default:return 1}}
func securityNormalizeDigest(value string)string{return strings.TrimPrefix(strings.ToLower(strings.TrimSpace(value)),"sha256:")}
func securityEdgeDigest(values ...string)string{hash:=sha256.New();for _,value:=range values{_,_=hash.Write([]byte(value));_,_=hash.Write([]byte{0})};return hex.EncodeToString(hash.Sum(nil))}
func securityUint(value uint64)string{if value==0{return "0"};digits:=[20]byte{};index:=len(digits);for value>0{index--;digits[index]=byte('0'+value%10);value/=10};return string(digits[index:])}

var _ apiserver.SecurityEdgeService=(*securityEdge)(nil)
